import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"主从模式","description":"","frontmatter":{},"headers":[],"relativePath":"database/mysql/basic/replication.md","filePath":"database/mysql/basic/replication.md"}`),a={name:`database/mysql/basic/replication.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="主从模式" tabindex="-1">主从模式 <a class="header-anchor" href="#主从模式" aria-label="Permalink to “主从模式”">​</a></h1><ul><li>主从复制是指一台服务器充当主数据库服务器，另一台或多台服务器充当从数据库服务器，主服务器中的数据自动复制到从服务器之中。</li><li>对于多级复制，数据库服务器即可充当主机，也可充当从机。MySQL主从复制的基础是主服务器对数据库修改记录二进制日志，从服务器通过主服务器的二进制日志自动执行更新。</li></ul><h2 id="复制原理" tabindex="-1">复制原理 <a class="header-anchor" href="#复制原理" aria-label="Permalink to “复制原理”">​</a></h2><ul><li>Slave上面的IO进程连接上Master，并请求从指定日志文件的指定位置（或者从最开始的日志）之后的日志内容。</li><li>Master接收到来自Slave的IO进程的请求后，负责复制的IO进程会根据请求信息读取日志指定位置之后的日志信息，返回给Slave的IO进程。返回信息中除了日志所包含的信息之外，还包括本次返回的信息已经到Master端的bin-log文件的名称以及bin-log的位置。</li><li>Slave的IO进程接收到信息后，将接收到的日志内容依次添加到Slave端的relay-log文件的最末端，并将读取到的Master端的 bin-log的文件名和位置记录到master-info文件中，以便在下一次读取的时候能够清楚的告诉Master从何处开始读取日志。</li><li>Slave的Sql进程检测到relay-log中新增加了内容后，会马上解析relay-log的内容成为在Master端真实执行时候的那些可执行的内容，并在自身执行。</li></ul><h2 id="搭建主从" tabindex="-1">搭建主从 <a class="header-anchor" href="#搭建主从" aria-label="Permalink to “搭建主从”">​</a></h2><ul><li>参考文档：<a href="https://juejin.cn/post/6844903921677238285" target="_blank" rel="noreferrer">https://juejin.cn/post/6844903921677238285</a></li></ul>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};